const msg = items[0].json.message;
const chatId = msg.chat.id;
const text = msg.text || '';

if (chatId !== 316228407) {
  return [{json: {response: 'Unauthorized', chatId, isSSH: false}}];
}

let response = '';
let command = text.trim().toLowerCase();
let isSSH = false;
let sshCmd = '';

if (command === '/start' || command === '/help') {
  response = '🤖 *Bot Commands:*\n/status - Server status
/backup - Manual backup DB
/health - Health check
/restart <service> - Restart service
/logs <service> - Show recent logs
/help - Show this message';
} else if (command === '/status') {
  response = '🔄 Getting server status...';
  isSSH = true;
  sshCmd = 'uptime && free -h && df -h /';
} else if (command === '/backup') {
  response = '🔄 Starting manual backup...';
  isSSH = true;
  sshCmd = '/root/backup_db.sh';
} else if (command === '/health') {
  response = '🔄 Running health check...';
  isSSH = true;
  sshCmd = '/root/health_check.sh';
} else if (command.startsWith('/restart ')) {
  const svc = command.split(' ')[1];
  response = '🔄 Restarting ' + svc + '...';
  isSSH = true;
  sshCmd = 'systemctl restart ' + svc + ' && echo

';
} else if (command.startsWith('/logs ')) {
  const svc = command.split(' ')[1];
  response = '🔄 Getting logs for ' + svc + '...';
  isSSH = true;
  sshCmd = 'journalctl -u ' + svc + ' -n 20 --no-pager';
} else {
  response = '❓ Unknown command. Type /help for commands.';
}

return [{json: {response, chatId, command, isSSH, sshCmd}}];
